int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    size_t num_pairs = 0;
    const char *start = in;

    while (num_pairs < max_pairs) {
        const char *eq = strchr(start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - start);
        keys_out[num_pairs] = malloc(klen + 1);
        strncpy(keys_out[num_pairs], start, klen);
        keys_out[num_pairs][klen] = '\0';

        const char *val_start = eq + 1;
        if (*val_start == '"') {
            const char *quote_end = strchr(val_start + 1, '"');
            if (!quote_end) break;
            size_t vlen = (size_t)(quote_end - val_start - 1);
            vals_out[num_pairs] = malloc(vlen + 1);
            strncpy(vals_out[num_pairs], val_start + 1, vlen);
            vals_out[num_pairs][vlen] = '\0';
            start = quote_end + 1;
        } else {
            const char *next_eq = strchr(eq + 1, '=');
            size_t vlen = next_eq ? (size_t)(next_eq - val_start) : strlen(val_start);
            vals_out[num_pairs] = malloc(vlen + 1);
            strncpy(vals_out[num_pairs], val_start, vlen);
            vals_out[num_pairs][vlen] = '\0';
            start = next_eq ? next_eq : val_start + vlen;
        }

        num_pairs++;
        if (*start == ' ') start++;
    }

    return num_pairs;
}

